#!/usr/bin/env bash
# Check that SBrain stays portable across coding agents.
#
# Usage: scripts/check.sh [--fix]
#   --fix  regenerate the generated files (each skill's Codex agents/openai.yaml and the portable
#          copy of comment-sicko) before checking.
#
# Fails on: a skill whose frontmatter breaks the Agent Skills spec (some agents silently drop it),
# a stale generated file, an adapter that is missing a Cursor name the skills use, a relative link
# that resolves nowhere, a shell script that doesn't parse, or JSON that doesn't parse. Warns on
# links that leave skills/, because a skills-only install doesn't have those files.
set -uo pipefail

ROOT=$(cd "$(dirname "$0")/.." && pwd)
cd "$ROOT"
fix=0
[ "${1:-}" = "--fix" ] && fix=1

python3 -I - "$fix" <<'PY'
import json, os, re, sys

fix = sys.argv[1] == "1"
failures, warnings = [], []
fail = failures.append
warn = warnings.append

def frontmatter(path):
    text = open(path, encoding="utf-8").read()
    match = re.match(r"^---\n(.*?)\n---\n", text, re.S)
    return (match.group(1) if match else None), text

def description(fm):
    # The decoded description: plain, single- or double-quoted, or a folded (>) or literal (|) block.
    raw = re.search(r"^description:[ \t]*(.*?)(?=^[A-Za-z][\w-]*:|\Z)", fm or "", re.S | re.M)
    raw = raw.group(1).strip() if raw else ""
    head, _, rest = raw.partition("\n")
    if head[:1] in (">", "|"):
        lines = [line.strip() for line in rest.splitlines() if line.strip()]
        return (" " if head[0] == ">" else "\n").join(lines)
    text = " ".join(line.strip() for line in raw.splitlines())
    if len(text) > 1 and text[0] == text[-1] == "'":
        return text[1:-1].replace("''", "'")
    if len(text) > 1 and text[0] == text[-1] == '"':
        return text[1:-1].replace('\\"', '"').replace("\\\\", "\\")
    return text

# 1. Agent Skills frontmatter, and the Codex opt-out file generated from disable-model-invocation.
OPENAI_YAML = (
    "# Generated by SBrain scripts/check.sh --fix. In Codex, load this skill only when a user or\n"
    "# another skill asks for it, matching its disable-model-invocation flag.\n"
    "policy:\n"
    "  allow_implicit_invocation: false\n"
)
for name in sorted(os.listdir("skills")):
    folder = os.path.join("skills", name)
    path = os.path.join(folder, "SKILL.md")
    if not os.path.isdir(folder):
        continue
    if not os.path.isfile(path):
        fail("%s has no SKILL.md" % folder)
        continue
    fm, _ = frontmatter(path)
    if fm is None:
        fail("%s has no frontmatter" % path)
        continue
    declared = re.search(r"^name:\s*(\S+)\s*$", fm, re.M)
    if not declared or declared.group(1) != name:
        fail("%s: name must be %r to match its folder" % (path, name))
    if not re.fullmatch(r"[a-z0-9]+(-[a-z0-9]+)*", name) or len(name) > 64:
        fail("%s: folder name breaks the Agent Skills naming rule" % folder)
    desc = description(fm)
    if not desc or len(desc) > 1024:
        fail("%s: description must be 1 to 1024 characters (has %d)" % (path, len(desc)))
    opt_out = os.path.join(folder, "agents", "openai.yaml")
    wants = re.search(r"^disable-model-invocation:\s*true\s*$", fm, re.M) is not None
    has = os.path.isfile(opt_out) and open(opt_out).read() == OPENAI_YAML
    if fix:
        if wants and not has:
            os.makedirs(os.path.dirname(opt_out), exist_ok=True)
            open(opt_out, "w").write(OPENAI_YAML)
        elif not wants and os.path.isfile(opt_out):
            os.remove(opt_out)
            if not os.listdir(os.path.dirname(opt_out)):
                os.rmdir(os.path.dirname(opt_out))
    elif wants != has:
        fail("%s is stale; run scripts/check.sh --fix" % opt_out)

# 2. The portable comment-sicko copy that agents without agent files read.
source, copy = "agents/comment-sicko.md", "skills/skiddle-mode/references/agents/comment-sicko.md"
if fix:
    os.makedirs(os.path.dirname(copy), exist_ok=True)
    open(copy, "w").write(open(source).read())
elif not os.path.isfile(copy) or open(copy).read() != open(source).read():
    fail("%s is stale; run scripts/check.sh --fix" % copy)

# 3. Every adapter maps every Cursor name the skills use.
TERMS = ["`Task`", "`AskQuestion`", "todolist", "subagent_type", "generalPurpose", "skiddle-agent",
         "comment-sicko", "readonly", "environment", "run_in_background", "resume", "file_attachments",
         "claude-opus", "sbrain-models", "ranscripts", "/loop"]
harness = "skills/skiddle-mode/references/harness"
index = open(os.path.join(harness, "README.md")).read()
for adapter in sorted(os.listdir(harness)):
    if adapter == "README.md" or not adapter.endswith(".md"):
        continue
    if "(%s)" % adapter not in index:
        fail("%s/README.md does not list %s" % (harness, adapter))
    text = open(os.path.join(harness, adapter)).read()
    for term in TERMS:
        if term not in text:
            fail("%s/%s has no row for %s" % (harness, adapter, term))
for listed in re.findall(r"\]\(([a-z-]+\.md)\)", index):
    if not os.path.isfile(os.path.join(harness, listed)):
        fail("%s/README.md lists missing %s" % (harness, listed))

# 4. Relative links in every Markdown file. Links from skills/ that leave skills/ are warnings.
skills_root = os.path.realpath("skills")
outside = {}
for dirpath, dirnames, files in os.walk("."):
    dirnames[:] = [d for d in dirnames if d != ".git"]
    for f in files:
        if not f.endswith(".md"):
            continue
        path = os.path.join(dirpath, f)
        text = open(path, encoding="utf-8").read()
        text = re.sub(r"```.*?```", "", text, flags=re.S)
        for target in re.findall(r"\]\(([^)\s]+)\)", text):
            if re.match(r"^[a-z]+:", target) or target.startswith("#") or "<" in target:
                continue
            resolved = os.path.realpath(os.path.join(dirpath, target.split("#")[0]))
            if not os.path.exists(resolved):
                fail("%s links to missing %s" % (path, target))
            elif path.startswith("./skills/") and not resolved.startswith(skills_root + os.sep):
                outside.setdefault(path, set()).add(target)
for path, targets in sorted(outside.items()):
    warn("%s links outside skills/ (missing in a skills-only install): %s" % (path, ", ".join(sorted(targets))))

# 5. JSON parses.
for path in [".claude-plugin/plugin.json", ".claude-plugin/marketplace.json", "hooks/hooks.json"]:
    try:
        json.load(open(path))
    except Exception as error:
        fail("%s is not valid JSON: %s" % (path, error))

# 6. Every principle leaf is in the skiddle-mode Principles index, and every entry has a leaf.
# A leaf the index doesn't list never triggers. An entry without a leaf points nowhere.
router = open("skills/skiddle-mode/SKILL.md", encoding="utf-8").read()
section = router.split("\n## Principles\n", 1)[-1].split("\n## ", 1)[0]
listed = set()
for line in section.splitlines():
    entry = re.match(r"^- \*\*(.+?)\*\*", line)
    if not entry:
        continue
    named = re.search(r"\(\*\*(principle-[a-z0-9-]+)\*\*\)", line)
    if named:
        listed.add(named.group(1))
    else:
        slug = re.sub(r"[^a-z0-9 -]", "", entry.group(1).rstrip(".").lower()).strip()
        listed.add("principle-" + re.sub(r"[ -]+", "-", slug))
leaves = set()
for name in os.listdir("skills"):
    if not name.startswith("principle-"):
        continue
    if os.path.isdir(os.path.join("skills", name)):
        leaves.add(name)
    else:
        fail("skills/%s is a file; a principle is a folder holding a SKILL.md" % name)
for name in sorted(listed - leaves):
    fail("skiddle-mode's Principles index lists %s, but skills/%s does not exist" % (name, name))
for name in sorted(leaves - listed):
    fail("skills/%s is not in skiddle-mode's Principles index, so it never triggers" % name)
for name in sorted(leaves):
    path = os.path.join("skills", name, "SKILL.md")
    if not os.path.isfile(path):
        continue  # Section 1 already reports the missing SKILL.md.
    fm, _ = frontmatter(path)
    if not description(fm).startswith("Apply"):
        fail("skills/%s: a principle's description starts with \"Apply\" and says when it applies" % name)

for line in warnings:
    print("warn  " + line)
for line in failures:
    print("FAIL  " + line)
sys.exit(1 if failures else 0)
PY
status=$?

for script in hooks/*.sh scripts/*.sh; do
  bash -n "$script" || { echo "FAIL  $script does not parse"; status=1; }
done

if command -v claude >/dev/null 2>&1; then
  claude plugin validate "$ROOT" >/dev/null 2>&1 || { echo "FAIL  claude plugin validate"; status=1; }
fi

[ "$status" = 0 ] && echo "SBrain portability check passed."
exit "$status"
